        return;
    if (thing->GetTC(&solid) && !solid->IsSolidToThing(&Player->GetParentThing()))
        return;
    if (thing->GetPhysicsTC()->IsPushableByHero())
        return;
    if (!thing->HasTC(TCI_BOSS))
        return;
