    const C3DVector& pos = thing->GetPos();
    C2DVector delta(pos.X - player_pos.X, pos.Y - player_pos.Y);
    float radii = Player->GetRadius() + thing->GetPhysicsTC()->GetRadius();
    if (fabs(pos.Z - player_pos.Z) < radii) {
