    action.PShot = 0; action.PerformAction();
    if (carrying.removeCount != 0) return Fail(2);
    action.PShot = &shotThing; shotThing.dead = true; action.PerformAction();
    if (carrying.removeCount != 0 || shotThing.addCount != 0) return Fail(3);
